macro_rules! deps {
    () => {
        RingBuffer!();
    };
}

macro_rules! Chunk {
    () => {
        deps!();
        # [doc = " A fixed capacity smart array."] # [doc = ""] # [doc = " An inline array of items with a variable length but a fixed, preallocated"] # [doc = " capacity given by the `N` type."] # [doc = ""] # [doc = " It's 'smart' because it's able to reorganise its contents based on expected"] # [doc = " behaviour. If you construct one using `push_back`, it will be laid out like"] # [doc = " a `Vec` with space at the end. If you `push_front` it will start filling in"] # [doc = " values from the back instead of the front, so that you still get linear time"] # [doc = " push as long as you don't reverse direction. If you do, and there's no room"] # [doc = " at the end you're pushing to, it'll shift its contents over to the other"] # [doc = " side, creating more space to push into. This technique is tuned for"] # [doc = " `Chunk`'s expected use case in [im::Vector]: usually, chunks always see"] # [doc = " either `push_front` or `push_back`, but not both unless they move around"] # [doc = " inside the tree, in which case they're able to reorganise themselves with"] # [doc = " reasonable efficiency to suit their new usage patterns."] # [doc = ""] # [doc = " It maintains a `left` index and a `right` index instead of a simple length"] # [doc = " counter in order to accomplish this, much like a ring buffer would, except"] # [doc = " that the `Chunk` keeps all its items sequentially in memory so that you can"] # [doc = " always get a `&[A]` slice for them, at the price of the occasional"] # [doc = " reordering operation. The allocated size of a `Chunk` is thus `usize` * 2 +"] # [doc = " `A` * `N`."] # [doc = ""] # [doc = " This technique also lets us choose to shift the shortest side to account for"] # [doc = " the inserted or removed element when performing insert and remove"] # [doc = " operations, unlike `Vec` where you always need to shift the right hand side."] # [doc = ""] # [doc = " Unlike a `Vec`, the `Chunk` has a fixed capacity and cannot grow beyond it."] # [doc = " Being intended for low level use, it expects you to know or test whether"] # [doc = " you're pushing to a full array, and has an API more geared towards panics"] # [doc = " than returning `Option`s, on the assumption that you know what you're doing."] # [doc = " Of course, if you don't, you can expect it to panic immediately rather than"] # [doc = " do something undefined and usually bad."] # [doc = ""] # [doc = " ## Isn't this just a less efficient ring buffer?"] # [doc = ""] # [doc = " You might be wondering why you would want to use this data structure rather"] # [doc = " than a [`RingBuffer`][RingBuffer], which is similar but doesn't need to"] # [doc = " shift its content around when it hits the sides of the allocated buffer. The"] # [doc = " answer is that `Chunk` can be dereferenced into a slice, while a ring buffer"] # [doc = " can not. You'll also save a few cycles on index lookups, as a `Chunk`'s data"] # [doc = " is guaranteed to be contiguous in memory, so there's no need to remap logical"] # [doc = " indices to a ring buffer's physical layout."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use sized_chunks::Chunk;"] # [doc = " // Construct a chunk with a 64 item capacity"] # [doc = " let mut chunk = Chunk::<i32, 64>::new();"] # [doc = " // Fill it with descending numbers"] # [doc = " chunk.extend((0..64).rev());"] # [doc = " // It derefs to a slice so we can use standard slice methods"] # [doc = " chunk.sort();"] # [doc = " // It's got all the amenities like `FromIterator` and `Eq`"] # [doc = " let expected: Chunk<i32, 64> = (0..64).collect();"] # [doc = " assert_eq!(expected, chunk);"] # [doc = " ```"] # [doc = ""] # [doc = " [im::Vector]: https://docs.rs/im/latest/im/vector/enum.Vector.html"] # [doc = " [RingBuffer]: ../ring_buffer/struct.RingBuffer.html"] pub struct Chunk < A , const N : usize > { left : usize , right : usize , data : MaybeUninit < [A ; N] > , }
    };
}

Chunk!();